inline LocalizedMessage settingsDiagnosticMessage(std::string_view language,SettingsDiagnosticMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=settingsDiagnosticMessageKeyCount)return {};
    const auto &source=settingsDiagnosticLocalePacks()[0];const auto *selected=&source;for(const auto &pack:settingsDiagnosticLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string settingsDiagnosticEnglish(SettingsDiagnosticMessageKey key){
    const auto text=settingsDiagnosticMessage("en",key).text;return text.find('{')==text.npos?std::string(text):std::string{};
}
// Fixed English suffix-placeholder extraction only. Does NOT accept, validate or sanitize a raw error.
inline std::string settingsDiagnosticEnglishPrefix(SettingsDiagnosticMessageKey key){
    const auto text=settingsDiagnosticMessage("en",key).text;const auto at=text.find("{error}");
    return at!=text.npos&&at+7==text.size()?std::string(text.substr(0,at)):std::string{};
}
